<?php
require_once __DIR__.'/config.php';
$s=db()->prepare('SELECT * FROM products WHERE id=? AND is_active=1'); $s->execute([(int)($_GET['id']??0)]); $p=$s->fetch();
if(!$p){http_response_code(404);exit('ไม่พบสินค้า');}
$sizes=array_values(array_filter(array_map('trim',preg_split('/[,|]/',(string)$p['sizes'])))); $page_title=$p['name'].' | '.STORE_NAME; require __DIR__.'/partials_header.php';
?>
<link rel="stylesheet" href="assets/cart.css">
<main class="container"><section class="panel product-detail"><img src="<?=e($p['image_url'])?>" alt="<?=e($p['name'])?>"><div class="product-detail-copy"><div class="eyebrow"><?=e($p['brand'])?> · <?=['men'=>'ผู้ชาย','women'=>'ผู้หญิง','kids'=>'เด็ก'][$p['category']]?></div><h1><?=e($p['name'])?></h1><div class="price product-price">฿<?=number_format((float)$p['price'],2)?></div><p><?=nl2br(e($p['description']))?></p><p><b>สี:</b> <?=e($p['color'])?></p><p><b>ไซซ์:</b> <?=e($p['sizes'])?></p><p class="muted">คงเหลือ <?=$p['stock']?> ชิ้น</p><?php if ((int)$p['stock'] > 0): ?><form method="post" action="cart.php" class="add-cart-form"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="hidden" name="color" value="<?=e($p['color'])?>"><input type="hidden" name="return_to" value="cart.php"><?php if($sizes): ?><label>เลือกไซซ์<select name="size"><?php foreach($sizes as $size): ?><option value="<?=e($size)?>"><?=e($size)?></option><?php endforeach; ?></select></label><?php endif; ?><label>จำนวน<input type="number" name="quantity" min="1" max="<?=$p['stock']?>" value="1"></label><button class="button" type="submit">เพิ่มลงตะกร้า</button></form><?php else: ?><button class="button" disabled>สินค้าหมดชั่วคราว</button><?php endif; ?></div></section></main><?php require __DIR__.'/partials_footer.php'; ?>
